// Matriz de controles (SIM-MOTOR-01 §6.3): cada control admitido por el plan tiene una correspondencia causal y una ruta de parámetros. El contraste lo ejecuta con distribuciones ANTES del sorteo
// (misma entrada salvo el control): un control «activo» que no cambia ninguna magnitud sería un defecto. Lo exclusivo del detallado se declara sin efecto aparente en SIM.
import { probeVector, diffVectors } from './probe.js';

const STYLE_ROWS = [
  ['organizedPace', 'Ritmo organizado', 'Duración esperada por control (selection.organizedDurationFactor × neutralSecondsPerControl), limitada por volume.secondsPerControlBounds.', ['selection.organizedDurationFactor', 'volume.neutralSecondsPerControl', 'volume.secondsPerControlBounds']],
  ['transition', 'Transición', 'Probabilidad de ataque directo tras robo o rebote defensivo (selection.transitionAttemptOddsRatio sobre selection.direct.attemptAfter*) y tiempo por control de transición.', ['selection.transitionAttemptOddsRatio', 'selection.direct.attemptAfterLiveSteal', 'selection.direct.attemptAfterDefensiveRebound', 'derived.transitionPaceFactor']],
  ['elaboration', 'Elaboración', 'Odds del pase final en finalizaciones que lo admiten (assist.eligibleFinalPassP0 × selection.elaborationContinuationWeightFactor); no genera pases uno a uno.', ['selection.elaborationContinuationWeightFactor', 'assist.eligibleFinalPassP0']],
  ['finishPreference', 'Prioridad de finalización', 'Mezcla exterior/interior de zonas (selection.orientationThree / orientationInside).', ['selection.orientationThree', 'selection.orientationInside']],
  ['freedom', 'Libertad', 'Peso del entrenador frente a la lectura de los jugadores (selection.freedom) y parte de decisiones espontáneas (acceptanceFloor + libertad) × lectura.', ['selection.freedom', 'selection.direct.acceptanceFloor', 'selection.readingMix']],
  ['offensiveRisk', 'Riesgo ofensivo', 'Inclinación entre opciones de distinto riesgo estimado (selection.offensiveRiskPreferenceTilt × riesgo de bote o pase).', ['selection.offensiveRiskPreferenceTilt', 'outcomes.base.turnover', 'outcomes.controlSensitivity']],
  ['afterShot', 'Después del tiro', 'Jugadores asignados al rebote ofensivo (rebound.offensiveReboundAssignmentTarget) y oportunidad de transición del rival (rebound.balance.unreadyReturnerOpportunityOddsRatio).', ['rebound.offensiveReboundAssignmentTarget', 'rebound.balance.unreadyReturnerOpportunityOddsRatio']],
];
const DEFSTYLE_ROWS = [
  ['help', 'Ayudas', 'Probabilidad de ayuda adicional (defense.styles.additionalHelpOddsRatio sobre opportunity.helpProbability): baja la conversión interior y abre el exterior.', ['defense.styles.additionalHelpOddsRatio', 'opportunity.helpProbability', 'opportunity.helperQualityLogit']],
  ['pressure', 'Presión al balón', 'Elección de presión cercana (defense.styles.closePressureChoiceOddsRatio): más pérdidas y faltas defensivas, más calidad cuando se supera.', ['defense.styles.closePressureChoiceOddsRatio', 'defense.choiceReferences.closePressureChoiceP0', 'defense.pressure.closePressureBeatenWeightFactor']],
  ['receivers', 'Defensa de receptores', 'Negación de receptores (defense.styles.receiverDenialChoiceOddsRatio): reduce la calidad de las fichas con receptor.', ['defense.styles.receiverDenialChoiceOddsRatio', 'defense.choiceReferences.receiverDenialChoiceP0']],
  ['steal', 'Riesgo de robo', 'Intento de robo (defense.styles.stealAttemptChoiceOddsRatio): más pérdidas robables y más faltas defensivas.', ['defense.styles.stealAttemptChoiceOddsRatio', 'defense.choiceReferences.stealAttemptGivenAccessP0']],
  ['protection', 'Protección del tiro', 'Protección interior/exterior (defense.styles.interior/exteriorProtectionChoiceWeight): desplaza la mezcla de zonas y la oposición por zona.', ['defense.styles.interiorProtectionChoiceWeight', 'defense.styles.exteriorProtectionChoiceWeight']],
];
export const CONTROL_ROWS = [
  ...STYLE_ROWS.map(([key, label, effect, params]) => ({ id: `styles.${key}`, group: 'estilo ofensivo', label, apply: (inp, v) => { inp.teams[0].plan.styles[key] = v; }, values: [1, 3, 5], effect, params, status: 'implementado' })),
  ...DEFSTYLE_ROWS.map(([key, label, effect, params]) => ({ id: `defStyles.${key}`, group: 'estilo defensivo (rival ataca)', label, apply: (inp, v) => { inp.teams[1].plan.defStyles[key] = v; }, values: [1, 3, 5], effect, params, status: 'implementado' })),
  { id: 'midrange', group: 'media distancia', label: 'Política de media distancia', apply: (inp, v) => { inp.teams[0].plan.midrange = v; }, values: ['avoid', 'openOnly', 'seek'], effect: 'Peso de las salidas de media distancia (selection.midrangePolicy): evitar, solo liberada o buscar con jugadores adecuados.', params: ['selection.midrangePolicy'], status: 'implementado' },
  { id: 'disposition', group: 'disposición', label: 'Disposición ofensiva', apply: (inp, v) => { inp.teams[0].plan.disposition = v; }, values: ['DIS01', 'DIS02', 'DIS03', 'DIS04', 'DIS05', 'DIS06'], effect: 'Disponibilidad de funciones: una ficha sin función compatible para un rol obligatorio no se juega; mezcla de zonas espontáneas por funciones exteriores/interiores. Sin bonus plano de acierto.', params: ['tablas heredadas: repertoire.dispositions y plays[*].roles.fn'], status: 'implementado' },
  { id: 'defense', group: 'organización defensiva', label: 'Organización defensiva', apply: (inp, v) => { inp.teams[1].plan.defense = v; }, values: ['ORG01', 'ORG02', 'ORG03', 'ORG04', 'ORG05'], effect: 'Reparto de responsabilidades por áreas y funciones (defenseRepertoire.organizations): quién protege primero cada zona; box and one usa el objetivo efectivo o ORG02.', params: ['defense.assignment', 'tablas heredadas: defenseRepertoire.organizations'], status: 'implementado' },
  { id: 'defense.ORG06', group: 'organización defensiva', label: 'Box and one (objetivo efectivo)', apply: (inp, v) => { inp.teams[1].plan.defense = 'ORG06'; inp.teams[1].plan.target = inp.teams[0].players[v === 'alt' ? 4 : 0].id; inp.teams[1].plan.targetAlt = inp.teams[0].players[4].id; }, values: ['objetivo', 'alt'], effect: 'Marca individual dedicada sobre el objetivo; si no está en pista se usa la alternativa y, si tampoco, fallbackOrg (ORG02).', params: ['defense.specials.boxAndOneDefaultFallback'], status: 'aproximado' },
  { id: 'coverage', group: 'cobertura de bloqueo', label: 'Cobertura de bloqueos', apply: (inp, v) => { inp.teams[1].plan.coverage = v; }, values: ['COB01', 'COB02', 'COB03', 'COB04'], effect: 'Contención de la cobertura (derivada de la carga comprometida): favorece el lanzamiento del manejador y perjudica al continuador; no se aplica a familias incompatibles ni a las que no usan bloqueo.', params: ['opportunity.coverageContainment', 'defense.coverage.committedActorLoad'], status: 'implementado' },
  { id: 'pressureHeight', group: 'altura de presión', label: 'Altura de presión', apply: (inp, v) => { inp.teams[1].plan.pressureHeight = v; }, values: ['normal', 'three_quarters', 'full'], effect: 'Interacción adelantada por control: pérdida, contacto, avance demorado (tiempo) y avance superado (transición); más carga de energía defensiva.', params: ['defense.pressure.newAdvancedInteractionBaseWeights', 'defense.pressure.advanceDurationFactorByHeight', 'defense.pressure.committedActorLoadByHeight'], status: 'implementado' },
  { id: 'playbook.priority', group: 'libro de fichas', label: 'Prioridades 1–5 del libro', apply: (inp, v) => { const pb = inp.teams[0].plan.playbook; pb.forEach((e, i) => { e.priority = i === 0 ? v : 3; }); }, values: [1, 3, 5], effect: 'Pesos de prioridad (selection.priorityWeights) sobre la mezcla de fichas; empates permitidos.', params: ['selection.priorityWeights'], status: 'implementado' },
  { id: 'coach.policy', group: 'entrenador', label: 'Política de rotación', apply: (inp, v) => { inp.teams[0].plan.coach = { ...(inp.teams[0].plan.coach ?? {}), policy: v }; }, values: ['ENTREF01', 'ENTREF02', 'ENTREF03'], effect: 'Umbrales de energía, permanencias mínimas y protección de faltas en la rotación básica (se contrasta en la distribución de sustituciones, no en el vector de tramo).', params: ['tablas heredadas: coach.policies'], status: 'implementado', rotation: true },
  // Exclusivos del detallado: se declaran sin efecto aparente en SIM
  ...[['marks', 'Marcas individuales'], ['navigation', 'Navegación de bloqueos'], ['specials', 'Especiales defensivas (ESPD01–03)'], ['throwInBook', 'Libro y respuestas de saque'], ['defense.roles', 'Roles defensivos D01–D12'], ['offensiveRoles', 'Roles ofensivos O01–O15 (orientan candidatos en el detallado)']]
    .map(([id, label]) => ({ id, group: 'exclusivo del detallado', label, apply: null, values: [], effect: 'Sin efecto aparente en SIM-MOTOR-01: la entrada se acepta y se declara como ignorada (identity.ignoredInput).', params: [], status: 'exclusivo del detallado' })),
];

export function controlContrasts(ctx, input) {
  const base = probeVector(ctx, input); const out = [];
  for (const row of CONTROL_ROWS) {
    if (!row.apply || row.rotation) { out.push({ id: row.id, group: row.group, label: row.label, status: row.status, values: row.values, changed: [], note: row.rotation ? 'contraste de rotación (ver pruebas)' : 'sin efecto aparente declarado' }); continue; }
    const per = []; const any = new Set();
    for (const v of row.values) { const copy = JSON.parse(JSON.stringify(input)); row.apply(copy, v); let vec; try { vec = probeVector(ctx, copy).vector; } catch (e) { per.push({ value: v, error: e.message }); continue; } const d = diffVectors(base.vector, vec); d.forEach((x) => any.add(x.key)); per.push({ value: v, changedKeys: d.length, top: d.sort((a, b) => Math.abs(b.delta / (Math.abs(b.base) || 1)) - Math.abs(a.delta / (Math.abs(a.base) || 1))).slice(0, 4).map((x) => `${x.key}:${x.delta >= 0 ? '+' : ''}${x.delta.toExponential(2)}`) }); }
    out.push({ id: row.id, group: row.group, label: row.label, status: row.status, values: row.values, effect: row.effect, params: row.params, changed: [...any].sort(), per });
  }
  return out;
}
